"""Export the Christmas choreography (choreo_xmas.py) to RP2040/dance_xmas.py
(export_elf_rp2040.py reuses this for the Elf edition).

python3 export_xmas_rp2040.py <path/to/RP2040/dance_xmas.py>
"""
import json
import os
import sys

OUT = os.path.join(os.path.dirname(os.path.abspath(__file__)), "out")


def main(dst, prefix="xmas", names=("lyrical", "classic", "grand"), edition="Christmas"):
    lines = [
        "# Coglet {} dance choreography -- GENERATED by dj/export_{}_rp2040.py".format(edition, prefix),
        "# from dj/choreo_{0}.py, which uses the same scores as the music (dj/{0}.py).".format(prefix),
        "# Do not edit by hand. Loaded by music.py only when a {} dance runs.".format(edition),
        "#",
        "# moves: (time_ms_from_music_start, move, arg)",
        "#   to:    arg = (servo, angle[, speed_deg_s])",
        "#   pulse: arg = (servo, angle, hold_ms)",
        "",
        "TRACKS = {",
    ]
    for name in names:
        with open(os.path.join(OUT, "{}_{}_choreo.json".format(prefix, name))) as f:
            c = json.load(f)
        lines.append('    "{}": {{'.format(name))
        lines.append('        "bpm": {},'.format(c["bpm"]))
        lines.append('        "duration_ms": {},'.format(c["duration_ms"]))
        lines.append('        "moves": (')
        for m in c["moves"]:
            arg = tuple(m["arg"]) if isinstance(m["arg"], list) else m["arg"]
            lines.append("            ({}, {!r}, {!r}),".format(m["t_ms"], m["move"], arg))
        lines.append("        ),")
        lines.append("    },")
    lines.append("}")
    with open(dst, "w") as f:
        f.write("\n".join(lines) + "\n")
    print("wrote", dst, os.path.getsize(dst), "bytes")


if __name__ == "__main__":
    main(sys.argv[1])
